<script setup>
import { computed, onMounted, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const templates=ref([]),selected=ref(null),form=ref({subject:'',content:''}),meta=ref(null),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),email=ref('')
const vars=computed(()=>[...(meta.value?.required_vars||[]),...(meta.value?.optional_vars||[])])
async function loadList(){loading.value=true;error.value='';try{templates.value=await props.api('mail/template/list');if(!selected.value&&templates.value.length)await open(templates.value[0])}catch(e){error.value=e.message}finally{loading.value=false}}
async function open(item){selected.value=item.name;error.value='';try{const data=await props.api(`mail/template/get?name=${encodeURIComponent(item.name)}`);meta.value=data;form.value={subject:data.subject||'',content:data.content||''}}catch(e){error.value=e.message}}
async function save(){saving.value=true;error.value='';try{await props.api('mail/template/save',{method:'POST',body:{name:selected.value,...form.value}});notice.value='邮件模板已保存。';await loadList()}catch(e){error.value=e.message}finally{saving.value=false}}
async function reset(){if(!window.confirm(`恢复“${meta.value?.label||selected.value}”默认内容？自定义模板将被移除。`))return;try{await props.api('mail/template/reset',{method:'POST',body:{name:selected.value}});await open({name:selected.value});notice.value='已恢复默认模板。';await loadList()}catch(e){error.value=e.message}}
async function test(){try{await props.api('mail/template/test',{method:'POST',body:{name:selected.value,...(email.value?{email:email.value}:{})}});notice.value='测试邮件已发送。'}catch(e){error.value=e.message}}
onMounted(loadList)
</script>
<template><section class="mail-view"><div class="page-title-row"><div><p class="eyebrow">SYSTEM / MAIL TEMPLATES</p><h1>邮件模板<span class="title-period">.</span></h1><p class="page-subtitle">编辑 Xboard 邮件主题与 HTML 内容，校验模板变量并发送测试邮件。</p></div><button class="refresh-button" @click="loadList">↻ <span>刷新</span></button></div><div class="mail-layout"><nav class="data-panel mail-list"><div class="panel-heading"><div><p class="eyebrow">TEMPLATES</p><h2>模板列表</h2></div></div><button v-for="item in templates" :key="item.name" :class="{selected:selected===item.name}" @click="open(item)"><span><b>{{item.label}}</b><small>{{item.name}}</small></span><i>{{item.customized?'自定义':'默认'}}</i></button><div v-if="loading" class="table-state">读取中…</div></nav><article class="data-panel mail-editor"><template v-if="meta"><div class="panel-heading"><div><p class="eyebrow">{{meta.name.toUpperCase()}} / EDITOR</p><h2>{{meta.label}}</h2></div><span class="status-label">{{meta.customized?'已自定义':'默认内容'}}</span></div><label class="mail-field">邮件主题<input v-model="form.subject" maxlength="255"></label><div class="mail-vars"><span>可用变量</span><code v-for="name in vars" :key="name"><span>{{ '{' }}{{ '{' }}{{ name }}{{ '}' }}{{ '}' }}</span></code></div><label class="mail-field">邮件正文（HTML）<textarea v-model="form.content" rows="18" spellcheck="false"></textarea></label><label class="mail-field">测试收件人 <small>留空则发送到当前管理员邮箱</small><input v-model.trim="email" type="email" placeholder="admin@example.com"></label></template><div v-else class="table-state">选择左侧模板开始编辑。</div><p v-if="error" class="notice">{{error}}</p><p v-if="notice" class="notice success">{{notice}}</p><footer v-if="meta" class="config-actions"><button class="danger-action" @click="reset">恢复默认</button><button @click="test">发送测试邮件</button><button class="save-button" :disabled="saving" @click="save">{{saving?'保存中…':'保存模板'}}</button></footer></article></div></section></template>
